def apply(inputs, premises):
    spans = []
    for span in inputs.get('source_spans', []):
        if isinstance(span, dict):
            spans.append(span)
    rows = answer_rows(inputs.get('semantic_answers', []))
    answered = answered_query_ids(rows)
    supported = set()
    source_output = inputs.get('source_output', {})
    if isinstance(source_output, dict):
        for row in source_output.get('statements', []):
            if not isinstance(row, dict):
                continue
            term = row.get('term')
            if term_has_constructor(term, 'acq_disclosure_v3') or term_has_constructor(term, 'permission') or term_has_constructor(term, 'prohibition'):
                for uid in row.get('support_ids', []):
                    supported.add(uid)
    queries = []
    i = 0
    while i < len(spans):
        uid = spans[i].get('id')
        text = normalized_text(spans[i].get('text', ''))
        employee = 'employee' in text or 'staff' in text or 'personnel' in text
        recipient_role = employee or has_any(text, ['contractor', 'consultant', 'agent', 'adviser', 'advisor', 'representative', 'officer', 'director'])
        operative = has_any(text, ['may disclose', 'may be disclosed', 'restrict access', 'restrict disclosure', 'disclosed only to', 'except in confidence', 'except to such', 'shall not disclose', 'not to disclose'])
        definition = has_any(text, ['affiliate” means', 'affiliate" means', 'representative” means', 'representative" means', 'control shall mean', 'control” shall mean', 'control" shall mean'])
        candidate = uid in supported or definition or (recipient_role and operative and ('information' in text or 'same' in text))
        if candidate:
            start = max(0, i - 2)
            unit_ids = []
            j = start
            while j <= i:
                unit_ids.append(spans[j].get('id'))
                j += 1
            effect_id = 'disclosure_focal_effect_' + str(uid)
            if effect_id not in answered:
                queries.append({'id': effect_id, 'operation': 'disclosure_focal_effect_v1', 'unit_ids': unit_ids})
            if employee and operative:
                owner_id = 'disclosure_employee_owner_' + str(uid)
                if owner_id not in answered:
                    queries.append({'id': owner_id, 'operation': 'disclosure_employee_owner_v1', 'unit_ids': unit_ids})
        i += 1
    return {'queries': queries}

