def apply(inputs, premises):
    spans = []
    for span in inputs.get('source_spans', []):
        if isinstance(span, dict):
            spans.append(span)
    old = inputs.get('source_output', {})
    statements = []
    unresolved = []
    if isinstance(old, dict):
        for row in old.get('statements', []):
            if not isinstance(row, dict):
                continue
            term = row.get('term')
            if isinstance(term, list) and term and term[0] == 'acq_disclosure_v3':
                continue
            statements.append(row)
        for item in old.get('unresolved', []):
            if isinstance(item, str) and item not in unresolved:
                unresolved.append(item)
    disposal_count = 0
    i = 0
    while i < len(spans):
        uid = spans[i].get('id')
        raw = spans[i].get('text', '')
        if not isinstance(raw, str):
            raw = str(raw)
        context = sp_context(spans, i, 2, 3)
        if sp_disposal_candidate(raw, context):
            positions = sp_action_positions(sp_low(raw))
            kinds = []
            if positions[0] >= 0:
                kinds.append('return')
            if positions[1] >= 0:
                kinds.append('destroy')
            scope = 'unit:' + str(uid)
            triggers = {}
            for kind in kinds:
                triggers[kind] = sp_trigger(raw, context, kind)
            linked = len(kinds) == 2 and triggers.get('return') == triggers.get('destroy')
            mode = 'linked' if linked else 'atomic'
            for kind in kinds:
                action_exception = sp_action_exception(spans, i, kind)
                support = [uid]
                support.extend(action_exception[3])
                action_id = scope + ':' + kind
                material = sp_material(raw, kind)
                timing = sp_timing(raw, kind)
                sp_add(statements, ['acq_disposal_action_v3', scope, action_id, kind, mode, material, triggers.get(kind), timing, action_exception[0], action_exception[1], action_exception[2], raw], support)
                disposal_count += 1
                if triggers.get(kind) == 'unresolved_trigger':
                    unresolved.append('action trigger unresolved for ' + action_id)
            if len(kinds) == 2:
                connector = 'or' if ' or ' in sp_low(raw) else 'and' if ' and ' in sp_low(raw) else 'split_or'
                if not linked:
                    connector = 'split_or'
                sp_add(statements, ['acq_disposal_link_v3', scope, scope + ':return', scope + ':destroy', connector, raw], [uid])
        i += 1
    sp_retention(spans, statements)
    sp_disclosure(spans, statements, unresolved)
    if disposal_count == 0:
        review = sp_complete_source_absence_review(spans)
        ids = []
        for span in spans:
            ids.append(span.get('id'))
        if review[0]:
            sp_add(statements, ['acq_complete_source_absence_v4', 'disposal_obligation'], ids)
            if review[1]:
                sp_add(statements, ['acq_complete_source_absence_v4', 'post_disposal_retention_effect'], ids)
        else:
            source_text = inputs.get('source_text', '')
            if not isinstance(source_text, str):
                source_text = str(source_text)
            sp_add(statements, ['acq_residual_v3', 'no_safely_composable_disposal_atom', source_text], ids)
            unresolved.append('no disposal atom acquired; complete-source absence review did not establish absence')
    complete = isinstance(old, dict) and bool(old.get('complete', False)) and len(sp_unique(unresolved)) == 0
    return {'statements': statements, 'complete': complete, 'unresolved': sp_unique(unresolved)}

def sp_disclosure(spans, out, unresolved):
    i = 0
    while i < len(spans):
        uid = spans[i].get('id')
        raw = spans[i].get('text', '')
        if not isinstance(raw, str):
            raw = str(raw)
        text = sp_low(raw)
        scope = 'unit:' + str(uid)
        definition_focus = sp_any(text, ['affiliate” means', 'affiliate" means', 'representative” means', 'representative" means', 'control shall mean', 'control” shall mean', 'control" shall mean'])
        permission = sp_any(text, ['may disclose', 'may be disclosed', 'may reveal', 'may divulge', 'may be shared', 'may share', 'restrict disclosure', 'restrict access', 'except in confidence', 'except its employees', 'only to disclose', 'disclosed only to', 'only share confidential information', 'reveal the information only to'])
        internal_exception = 'within its own organization' in text and sp_any(text, ['except on a "need-to-know" basis', 'except on a “need-to-know” basis', 'except on a need-to-know basis'])
        if internal_exception:
            permission = True
        if definition_focus:
            permission = False
        elliptical = 'obligations of the parties' in text and 'need to know' in text and not permission
        if elliptical:
            roles = []
            if sp_any(text, ['employee', 'staff', 'personnel']):
                roles.append('employee')
            if 'agent' in text:
                roles.append('agent')
            if 'representative' in text:
                roles.append('representative')
            for role in sp_unique(roles):
                sp_add(out, ['acq_disclosure_v3', scope, 'elliptical_recipient_permission_residual', 'receiving_party', role, 'receiving_party', 'required', 'not_stated', 'required', 'source_stated_ellipsis', raw], [uid])
        need = 'required' if sp_any(text, ['need to know', 'need-to-know', 'bona fide need']) else 'not_stated'
        extent = 'required' if sp_any(text, ['extent necessary', 'extent absolutely necessary', 'strictly necessary', 'reasonably necessary', 'disclosure is necessary']) else 'not_stated'
        confidentiality = 'written_required' if sp_any(text, ['bound in writing', 'written confidentiality agreement', 'mandatory non-disclosure agreement']) else 'required' if sp_any(text, ['subject to the provisions', 'duty of confidentiality', 'bound by obligations', 'terms no less stringent', 'terms and conditions no less protective', 'treat such confidential information']) else 'not_stated'
        effect = 'class_permission' if ('except' in text or internal_exception) else 'operative_permission'
        actor = 'Auditor' if 'auditor shall' in text else 'Visitor' if 'visitor' in text else 'receiving_party'
        if permission:
            has_employee = sp_any(text, ['employee', 'staff', 'personnel'])
            affiliate_employee = has_employee and re.search(r'\b(?:affiliate|affiliates|controlled entit(?:y|ies))\b[^.;]{0,140}\b(?:employee|employees|staff|personnel)\b', text, re.I) is not None
            direct_employee = has_employee and re.search(r'\b(?:its|recipient.s|receiving party.s)\b[^.;]{0,120}\b(?:employee|employees|staff|personnel)\b', text, re.I) is not None and not affiliate_employee
            employee_after_action = re.search(r'\b(?:disclos(?:e|ed)|access|divulg(?:e|ed)|reveal(?:ed)?|share(?:d)?)\b[^.;:]{0,180}\b(?:employee|employees|staff|personnel)\b', text, re.I) is not None
            if employee_after_action and not affiliate_employee:
                direct_employee = True
            if direct_employee:
                sp_add(out, ['acq_disclosure_v3', scope, effect, actor, 'employee', 'receiving_party', need, extent, confidentiality, 'source_stated_exception', raw], [uid])
            if affiliate_employee:
                sp_add(out, ['acq_disclosure_v3', scope, effect, actor, 'employee', 'controlled_entity', need, extent, confidentiality, 'source_stated_exception', raw], [uid])
            if internal_exception:
                sp_add(out, ['acq_disclosure_v3', scope, effect, actor, 'internal_personnel', 'receiving_party', need, extent, confidentiality, 'source_stated_exception', raw], [uid])
            if 'consultant' in text:
                sp_add(out, ['acq_disclosure_v3', scope, effect, actor, 'consultant', 'receiving_party', need, extent, confidentiality, 'source_stated_exception', raw], [uid])
            if 'contractor' in text:
                sp_add(out, ['acq_disclosure_v3', scope, effect, actor, 'contractor', 'receiving_party', need, extent, confidentiality, 'source_stated_exception', raw], [uid])
            if 'agent' in text:
                sp_add(out, ['acq_disclosure_v3', scope, effect, actor, 'agent', 'receiving_party', need, extent, confidentiality, 'source_stated_exception', raw], [uid])
            if sp_any(text, ['professional adviser', 'professional advisor', 'legal advisor', 'legal adviser', 'financial advisor', 'financial adviser']):
                sp_add(out, ['acq_disclosure_v3', scope, effect, actor, 'professional_adviser', 'receiving_party', need, extent, confidentiality, 'source_stated_exception', raw], [uid])
            if 'representative' in text and not sp_any(text, ['employees', 'consultants', 'contractors', 'agents', 'advisers', 'advisors']):
                sp_add(out, ['acq_disclosure_v3', scope, effect, actor, 'representative', 'receiving_party', need, extent, confidentiality, 'source_stated_exception', raw], [uid])
        prohibited = sp_any(text, ['shall not disclose', 'not disclose', 'not to disclose', 'will not without', 'not without']) and sp_any(text, ['others', 'other person', 'other organization', 'third party', 'third parties', 'anyone'])
        if prohibited and not permission and not definition_focus:
            authorization = sp_any(text, ['consent', 'written approval', 'written authorization'])
            cross_reference = sp_any(text, ['unless this agreement expressly permits', 'except as this agreement expressly permits', 'unless expressly permitted by this agreement'])
            exception = 'authorization_and_cross_reference' if authorization and cross_reference else 'authorization' if authorization else 'cross_reference' if cross_reference else 'source_stated_exception'
            sp_add(out, ['acq_disclosure_v3', scope, 'bounded_prohibition', actor, 'source_outsiders', 'source_bounded', 'not_stated', 'not_stated', 'not_stated', exception, raw], [uid])
            if sp_any(text, ['anyone', 'third party', 'third parties']):
                sp_add(out, ['acq_disclosure_v3', scope, 'bounded_prohibition', actor, 'third_parties', 'source_bounded', 'not_stated', 'not_stated', 'not_stated', exception, raw], [uid])
        i += 1
